// shift で「受け取った値に 1 を足す」残りの計算を関数 k として取り出します。k(2)
// の結果である 3 を 10 倍するため、全体の値は 30 になります。

console.log(reset(() => 1 + shift(k => k(2) * 10)));

// stop は、最も近い reset までの残りの計算を打ち切って 7 を返します。
// 内側の reset の有無で、どこまで打ち切られるかを比べます。
function stop() {
  return shift(() => 7);
}

console.log(reset(() => 100 + reset(() => 10 + stop())));
console.log(reset(() => 100 + 10 + stop()));

// shift 内で k を呼ばずに 42 をそのまま返すと、reset
// 内の残りの処理は実行されず、42 が全体の結果になります。

console.log(reset(() => {
  const value = shift(k => 42);
  console.log("ここには到達しない");
  return value + 1;
}));

// console.log で処理が移る順序を確認できます。k(2)
// で中断箇所から再開し、reset の末尾まで進んだあと、その結果を持って shift
// 内に戻ります。

console.log("1. reset の前");
const result = reset(() => {
  console.log("2. shift の前");
  const value = shift(k => {
    console.log("3. shift 内（再開前）");
    const resumed = k(2);
    console.log("5. shift 内（再開後）:", resumed);
    return resumed * 10;
  });
  console.log("4. 再開後:", value);
  return value + 1;
});
console.log("6. 最終結果:", result);

// 取り出した継続 k を reset の外へ返すと、後から繰り返し呼び出せます。

const k = reset(() => 10 + shift(k => k));
console.log(k(2));
console.log(k(5));

// 取り出した同じ継続 k を 2 と 3 でそれぞれ再開します。(1 + 2) と (1 + 3)
// が計算され、合計の 7 が返ります。

console.log(reset(() => 1 + shift(k => k(2) + k(3))));

// 継続を取り出す前に定義した変数 count は、再開のたびに引き継がれます。関数 next
// を呼ぶたびに値が増えます。

const next = reset(() => {
  let count = 0;
  shift(k => k);
  return ++count;
});
console.log(next(), next(), next());

// 再開した計算の中でさらに shift を実行できます。最初の継続 first
// と、そこから得られる 2 段目の継続 a・b をそれぞれ呼び出せます。

const first = reset(() => {
  function inner() {
    return shift(k => k) + shift(k => k);
  }
  return 10 + inner();
});
const a = first(2);
const b = first(5);
console.log(a(3), b(4), a(9));

// 候補の配列から要素を選ぶ choose 関数を shift で定義し、和が 10
// になるペアをすべて探索します。

function choose(items) {
  return shift(k => {
    for (const item of items) k(item);
  });
}

reset(() => {
  const x = choose([2, 4, 7]);
  const y = choose([3, 6, 8]);
  if (x + y === 10) {
    console.log(`${x} + ${y} = 10`);
  }
});

// choose が候補ごとに残りの計算を再開し、guard が失敗した枝を打ち切ります。
// place は盤面を枝ごとに新しく作ります。共有オブジェクトの変更は巻き戻りません。
function choose(values) {
  return shift(k => {
    for (let i = 0; i < values.length; i++) k(values[i]);
  });
}

function guard(condition) {
  if (!condition) shift(k => undefined);
}

function place(columns) {
  if (columns.length === 4) {
    console.log(JSON.stringify(columns));
    return;
  }
  const column = choose([0, 1, 2, 3]);
  const row = columns.length;
  for (let previous = 0; previous < row; previous++) {
    guard(columns[previous] !== column);
    guard(Math.abs(columns[previous] - column) !== row - previous);
  }
  place(columns.concat([column]));
}

// 配列の添字が行、値が列です（どちらも0始まり）。
reset(() => place([]));

// visitLeaves は再帰で木をたどり、葉を見つけるたびに中断します。
// sameFringe は2本の木を1枚ずつ進め、葉の並びを比べます。
function visitLeaves(tree, side) {
  if (Array.isArray(tree)) {
    visitLeaves(tree[0], side);
    visitLeaves(tree[1], side);
    return;
  }

  console.log(side + ": " + tree);
  shift(resume => ({ value: tree, resume }));
}

function sameFringe(left, right) {
  let leftStep = reset(() => visitLeaves(left, "left"));
  let rightStep = reset(() => visitLeaves(right, "right"));

  while (leftStep !== undefined && rightStep !== undefined) {
    if (leftStep.value !== rightStep.value) return false;
    leftStep = leftStep.resume();
    rightStep = rightStep.resume();
  }

  return leftStep === undefined && rightStep === undefined;
}

console.log(sameFringe([[1, 2], 3], [1, [2, 3]]));
console.log(sameFringe([[1, 2], 3], [1, [9, 3]]));

// flip は表と裏の両方を評価します。事象が起きた枝は 1、ほかの枝は 0 を返すため、
// 枝の重み付き和が事象の確率になります。
function flip(p) {
  return shift(resume => p * resume(true) + (1 - p) * resume(false));
}

function probabilityOf(event) {
  return reset(() => {
    const firstHeads = flip(0.25);
    const secondHeads = flip(0.75);
    return event(firstHeads, secondHeads) ? 1 : 0;
  });
}

const exactlyOneHead = probabilityOf((first, second) => first !== second);
const onlyFirstHead = probabilityOf((first, second) => first && !second);

console.log("P(exactly one head):", exactlyOneHead);
console.log("P(first is heads | exactly one head):", onlyFirstHead / exactlyOneHead);

// callCC は捕捉した継続へ値を渡します。
// 渡された継続を呼ぶと、呼び出し側の残りの計算を捨ててジャンプします。
function callCC(f) {
  return shift(k =>
    k(f(value => shift(ignored => k(value))))
  );
}

// この reset がプログラム全体の実行境界です。
// 内側に別の reset は置きません。callCC はここまでの残り全体を捕捉します。
reset(() => {
  // 継続を呼ばなければ、コールバックの戻り値で計算が続きます。
  const normal = callCC(k => 7);
  console.log("通常の戻り値:", normal);

  // 深い呼び出しからでも、callCC の位置へ値を渡して脱出できます。
  const found = callCC(exit => {
    function search() {
      for (let i = 1; i <= 10; i++) {
        if (i * i > 20) exit(i);
      }
    }
    search();
    console.log("脱出後なので実行されない");
    return -1;
  });
  console.log("探索結果:", found);

  let saved;
  let jumps = 0;
  const value = callCC(k => {
    saved = k;
    return 10;
  });

  // saved はこの出力を含め、プログラム末尾までの継続を保持します。
  // jumps の変更は巻き戻りません。同じ継続へ2回ジャンプします。
  console.log("再開した値:", value);
  if (jumps < 2) {
    jumps++;
    saved(value + 10);
    console.log("ジャンプ元には戻らない");
  }
  console.log("プログラム終了");
});

// perform は操作名・引数・継続を要求として返します。
// handle が要求を解釈して再開するので、program は状態の保存方法を知りません。
// 再開後の要求も同じハンドラーで扱います。この例は同期・単一ハンドラーです。
// 未知の操作はエラーにし、外側への転送やハンドラーの合成は扱いません。
function perform(operation, argument) {
  return shift(resume => ({ kind: "effect", operation, argument, resume }));
}

function handle(program, initialState) {
  let state = initialState;
  const logs = [];
  let step = reset(() => ({ kind: "done", value: program() }));
  while (step.kind === "effect") {
    let response;
    switch (step.operation) {
      case "get":
        response = state;
        break;
      case "put":
        state = step.argument;
        break;
      case "log":
        logs.push(step.argument);
        break;
      default:
        throw new Error("未処理の操作: " + step.operation);
    }
    step = step.resume(response);
  }
  return { value: step.value, state, logs };
}

function program() {
  const before = perform("get");
  perform("put", before + 1);
  const after = perform("get");
  perform("log", `${before} → ${after}`);
  return after * 2;
}

// 同じ計算を異なる初期状態で解釈します。
console.log(JSON.stringify(handle(program, 0)));
console.log(JSON.stringify(handle(program, 10)));
